 def submit_share(data):
  pg.evaluate('''data=>{const form=document.createElement('form');form.action=new URL('./share-target',location.href).href;form.method='POST';form.enctype='multipart/form-data';const text=document.createElement('input');text.name='text';text.value=data.text||'';form.append(text);const input=document.createElement('input');input.type='file';input.name='photos';input.multiple=true;const dt=new DataTransfer();for(const f of data.files){const bytes=Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0));dt.items.add(new File([bytes],f.name,{type:f.mimeType}));}input.files=dt.files;form.append(input);document.body.append(form);form.submit();}''',data)
